@layer components {
  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="title"]),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="title"]),
  :where([data-control-family="popup"][data-popup-kind="sheet"][data-slot="title"]),
  :where([data-control-family="popup"][data-popup-kind="drawer"][data-slot="title"]),
  :where([data-control-family="popup"][data-popup-kind="popover"][data-slot="title"]),
  :where([data-control-family="popup"][data-popup-kind="toast"][data-slot="title"]) {
    color: var(--cui-popup-title-foreground);
    font-size: var(--cui-popup-title-font-size);
    font-weight: var(--cui-popup-title-font-weight);
    line-height: var(--cui-popup-title-line-height);
    letter-spacing: var(--cui-popup-title-letter-spacing);
    text-wrap: balance;
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="description"]),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="description"]),
  :where([data-control-family="popup"][data-popup-kind="sheet"][data-slot="description"]),
  :where([data-control-family="popup"][data-popup-kind="drawer"][data-slot="description"]),
  :where([data-control-family="popup"][data-popup-kind="popover"][data-slot="description"]),
  :where([data-control-family="popup"][data-popup-kind="toast"][data-slot="description"]) {
    color: var(--cui-popup-description-foreground);
    font-size: var(--text-body);
    text-wrap: pretty;
  }

  :where([data-control-family="popup"][data-slot="arrow"]) {
    color: var(--cui-popup-background);
  }

  :where([data-control-family="popup"][data-slot="arrow"][data-side="top"]) {
    inset-block-end: -8px;
    rotate: 180deg;
  }

  :where([data-control-family="popup"][data-slot="arrow"][data-side="bottom"]) {
    inset-block-start: -8px;
  }

  :where([data-control-family="popup"][data-slot="arrow"][data-side="left"]) {
    right: -10px;
    rotate: 90deg;
  }

  :where([data-control-family="popup"][data-slot="arrow"][data-side="right"]) {
    left: -10px;
    rotate: -90deg;
  }

  :where([data-control-family="popup"][data-slot="arrow"][data-side="inline-start"]) {
    inset-inline-end: -10px;
    rotate: 90deg;
  }

  :where([data-control-family="popup"][data-slot="arrow"][data-side="inline-end"]) {
    inset-inline-start: -10px;
    rotate: -90deg;
  }

  :where([data-control-family="popup"][data-slot="arrow"][data-side="inline-start"]:dir(rtl)) {
    rotate: -90deg;
  }

  :where([data-control-family="popup"][data-slot="arrow"][data-side="inline-end"]:dir(rtl)) {
    rotate: 90deg;
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"]) {
    padding: calc(var(--spacing) * 1) calc(var(--spacing) * 2.5);
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="content"]),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="content"]),
  :where([data-control-family="popup"][data-popup-kind="sheet"][data-slot="content"]) {
    gap: calc(var(--spacing) * 4);
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="header"]),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="header"]) {
    gap: calc(var(--spacing) * 1.5);
    padding: calc(var(--spacing) * 4) calc(var(--spacing) * 4) 0;
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="body"]),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="body"]) {
    gap: calc(var(--spacing) * 4);
    padding-inline: calc(var(--spacing) * 4);
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="body"]:not(:has(~ [data-slot="footer"]))),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="body"]:not(:has(~ [data-slot="footer"]))) {
    padding-block-end: calc(var(--spacing) * 4);
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="footer"]),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="footer"]) {
    gap: calc(var(--spacing) * 2);
    padding: 0 calc(var(--spacing) * 4) calc(var(--spacing) * 4);
  }

  :where([data-control-family="popup"][data-popup-kind="sheet"][data-slot="header"]) {
    gap: calc(var(--spacing) * 1.5);
    padding: calc(var(--spacing) * 4);
  }

  :where([data-control-family="popup"][data-popup-kind="popover"][data-slot="header"]) {
    gap: calc(var(--spacing) * 1.5);
    padding-block-end: calc(var(--spacing) * 3);
  }

  :where([data-control-family="popup"][data-popup-kind="popover"][data-popup-part="surface"][data-padding="default"]),
  :where([data-control-family="popup"][data-popup-kind="hover-card"][data-popup-part="surface"]) {
    padding: calc(var(--spacing) * 4);
  }

  :where([data-control-family="popup"][data-popup-kind="hover-card"][data-slot="trigger"]:is(a)) {
    border-radius: var(--radius-sm);
    color: var(--foreground);
    font-weight: var(--font-weight-medium);
    text-decoration-line: underline;
    text-decoration-color: var(--border);
    text-decoration-thickness: 1px;
    text-underline-offset: 2px;
    cursor: pointer;
    transition: text-decoration-color var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="popup"][data-popup-kind="hover-card"][data-slot="trigger"]:is(a)[data-popup-open]) {
    text-decoration-color: var(--foreground);
  }

  @media (hover: hover) {
    :where([data-control-family="popup"][data-popup-kind="hover-card"][data-slot="trigger"]:is(a):hover) {
      text-decoration-color: var(--foreground);
    }
  }

  :where([data-control-family="popup"][data-popup-kind="navigation-menu"][data-slot="link"]) {
    text-decoration-line: none;
  }

  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="content"]) {
    text-align: start;
  }

  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="content"][data-starting-style]),
  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="content"][data-ending-style]) {
    opacity: 0;
  }

  :where([data-control-family="button"][data-popup-part="close"][data-icon-only="true"]) {
    --_popup-button-root-close-opacity: 70%;
    opacity: var(--_popup-button-root-close-opacity);
  }

  :where(
    [data-control-family="popup"][data-surface="modal"] > [data-control-family="button"][data-popup-part="close"][data-icon-only="true"]
  ) {
    position: absolute;
    inset-block-start: var(--cui-popup-close-inset);
    inset-inline-end: var(--cui-popup-close-inset);
  }

  :where(
    [data-control-family="popup"][data-surface="modal"]:has(> [data-control-family="button"][data-popup-part="close"])
      [data-control-family="popup"][data-slot="header"]
  ) {
    padding-inline-end: calc(var(--cui-popup-close-inset) + var(--control-h-xs) + var(--spacing) * 2);
  }

  @media (hover: hover) {
    :where([data-control-family="button"][data-popup-part="close"][data-icon-only="true"]:hover) {
      --_popup-button-root-close-opacity: 100%;
      opacity: var(--_popup-button-root-close-opacity);
    }
  }
}

@property --cui-popup-title-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-popup-title-font-size {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-popup-title-font-weight {
  syntax: "<number>";
  inherits: true;
  initial-value: 400;
}

@property --cui-popup-title-line-height {
  syntax: "<number>";
  inherits: true;
  initial-value: 1.5;
}

@property --cui-popup-title-letter-spacing {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-popup-description-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-popup-close-inset {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@layer components {
  :where([data-control-family="popup"][data-popup-kind="model-switcher"][data-slot="hint"]) {
    margin-inline-start: auto;
    padding-inline-start: calc(var(--spacing) * 4);
    font-size: var(--text-micro);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="trigger-menu"][data-slot="group-label"]) {
    padding-block: calc(var(--spacing) * 1) calc(var(--spacing) * 0.5);
    text-transform: uppercase;
    font-size: var(--text-micro);
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.08em;
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="trigger-menu"][data-slot="empty"]) {
    padding-block: calc(var(--spacing) * 2);
    font-size: var(--text-body);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="trigger-menu"][data-slot="icon"]) {
    inline-size: calc(var(--spacing) * 5);
    block-size: calc(var(--spacing) * 5);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="trigger-menu"][data-slot="list"]),
  :where([data-control-family="popup"][data-popup-kind="trigger-menu"][data-slot="group"]) {
    gap: calc(var(--spacing) * 0.5);
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="group"]),
  :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="group"]) {
    padding-block: calc(var(--spacing) * 1);
  }

  :where([data-control-family="popup"][data-popup-kind="combobox"][data-slot="group-label"]) {
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="combobox"][data-slot="item-indicator"]) {
    color: var(--foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="combobox"][data-slot="empty"]) {
    padding-block: calc(var(--spacing) * 6);
    text-align: center;
    font-size: var(--text-body);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-chrome="embedded"]) {
    border-radius: inherit;
    corner-shape: inherit;
  }

  :where([data-control-family="popup"][data-popup-kind="command"] > [data-control-family="scroll-area"][data-slot="root"]:last-child) {
    border-radius: inherit;
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="group"] [cmdk-group-heading]) {
    padding-inline: calc(var(--spacing) * 2);
    padding-block: calc(var(--spacing) * 1.5);
    text-transform: uppercase;
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.08em;
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="empty"]),
  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="loading"]) {
    padding-block: calc(var(--spacing) * 6);
    text-align: center;
    font-size: var(--text-body);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="input-wrapper"]) {
    border-start-start-radius: inherit;
    border-start-end-radius: inherit;
    gap: calc(var(--spacing) * 2);
    block-size: var(--control-h-lg);
    padding-inline: calc(var(--padding-x) * 1.25);
    border-block-end: 1px solid var(--cui-popup-separator-color);
    font-size: var(--text-body);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="input"]) {
    background: transparent;
    color: var(--foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="input"])::placeholder,
  :where([data-control-family="popup"][data-popup-kind="command"] [cmdk-group-heading]) {
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="input"]:disabled) {
    opacity: var(--disabled-opacity);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="group"]) {
    color: var(--foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="input-icon"]) {
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="dialog-root"]) {
    transition-property: grid-template-rows;
    transition-duration: var(--duration-slow);
    transition-timing-function: var(--ease-emphasized);
    transition-delay: var(--duration-fast);
  }

  :where([data-control-family="popup"][data-popup-kind="autocomplete"][data-slot="group-label"]) {
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="autocomplete"][data-slot="empty"]) {
    padding-block: calc(var(--spacing) * 6);
    text-align: center;
    font-size: var(--text-body);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-slot="item-text"]) {
    gap: calc(var(--spacing) * 2);
  }

  :where([data-control-family="popup"][data-popup-part="label"]) {
    padding-block: var(--cui-popup-label-padding-block);
    padding-inline: var(--cui-popup-label-padding-inline);
    color: var(--muted-foreground);
    font-size: var(--cui-popup-label-font-size);
    font-weight: var(--cui-popup-label-font-weight);
    letter-spacing: var(--cui-popup-label-letter-spacing);
    text-transform: var(--cui-popup-label-text-transform);
  }

  :where([data-control-family="popup"][data-popup-part="item"][data-inset]),
  :where([data-control-family="popup"][data-popup-part="label"][data-inset]),
  :where([data-control-family="popup"][data-popup-part="item"]:is([data-slot="checkbox-item"], [data-slot="radio-item"])) {
    padding-inline-start: var(--cui-popup-item-inset);
  }

  :where([data-control-family="popup"][data-popup-part="separator"]) {
    margin-block: calc(var(--spacing) * 1);
    margin-inline: var(--cui-popup-separator-inset);
    block-size: 1px;
    background-color: var(--cui-popup-separator-color);
  }

  :where([data-control-family="popup"][data-popup-part="shortcut"]) {
    margin-inline-start: auto;
    padding-inline-start: calc(var(--spacing) * 6);
    color: var(--cui-popup-shortcut-foreground);
    font-size: var(--cui-popup-shortcut-font-size);
    letter-spacing: var(--cui-popup-shortcut-letter-spacing);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="shortcut"]) {
    --cui-popup-shortcut-font-size: var(--text-label);
  }

  :where([data-control-family="popup"][data-slot="sub-trigger-indicator"]) {
    margin-inline-start: auto;
    padding-inline-start: calc(var(--spacing) * 4);
    line-height: 1;
  }

  :where([data-control-family="popup"][data-popup-part="bar"]) {
    --_popup-bar-item-radius: min(var(--cui-popup-item-radius), calc(var(--control-h-sm) / 2));
    --_popup-bar-padding: calc(var(--spacing) * 1);
    --cui-popup-radius: calc(
      var(--_popup-bar-item-radius) +
      clamp(0px, calc(var(--_popup-bar-item-radius) * 1000), var(--_popup-bar-padding))
    );
    --nest-radius: var(--_popup-bar-item-radius);
    padding: var(--_popup-bar-padding);
    gap: calc(var(--spacing) * 0.5);
    --cui-popup-background: var(--card);
    --cui-popup-shadow: var(--shadow-sm);
  }

  :where([data-control-family="popup"][data-popup-kind="navigation-menu"][data-slot="list"]) {
    gap: calc(var(--spacing) * 0.5);
  }

  :where([data-control-family="popup"][data-popup-part="navigation-link"]) {
    padding-block: calc(var(--spacing) * 2);
    padding-inline: calc(var(--spacing) * 3);
  }

  :where([data-control-family="popup"][data-popup-part="navigation-link"][data-variant="compact"]) {
    padding-block: 0;
  }

  :where([data-control-family="popup"][data-popup-kind="navigation-menu"][data-slot="positioner"]) {
    transition-property: inset-block-start, inset-inline-start, inset-block-end, inset-inline-end;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-emphasized);
  }

  :where([data-control-family="popup"][data-popup-kind="navigation-menu"][data-slot="popup"]) {
    transform-origin: var(--transform-origin);
    transition-property: opacity, inline-size, block-size, scale;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-emphasized);
  }

  :where([data-control-family="popup"][data-popup-kind="navigation-menu"][data-slot="popup"][data-starting-style]) {
    scale: 0.95;
    opacity: 0;
  }

  :where([data-control-family="popup"][data-popup-kind="navigation-menu"][data-slot="popup"][data-ending-style]) {
    opacity: 0;
    transition-duration: var(--duration-fast);
  }

  :where([data-control-family="popup"][data-popup-kind="navigation-menu"][data-slot="content"]) {
    transition-property: opacity, translate;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-emphasized);
  }

  :where(
    [data-control-family="popup"][data-popup-kind="navigation-menu"][data-slot="content"]:is([data-starting-style], [data-ending-style])
  ) {
    opacity: 0;
  }

  :where(
    [data-control-family="popup"][data-popup-kind="navigation-menu"][data-slot="content"][data-starting-style][data-activation-direction="left"]
  ),
  :where(
    [data-control-family="popup"][data-popup-kind="navigation-menu"][data-slot="content"][data-ending-style][data-activation-direction="right"]
  ) {
    translate: calc(var(--spacing) * -3) 0;
  }

  :where(
    [data-control-family="popup"][data-popup-kind="navigation-menu"][data-slot="content"][data-starting-style][data-activation-direction="right"]
  ),
  :where(
    [data-control-family="popup"][data-popup-kind="navigation-menu"][data-slot="content"][data-ending-style][data-activation-direction="left"]
  ) {
    translate: calc(var(--spacing) * 3) 0;
  }
}

@property --cui-popup-item-inset {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-popup-label-padding-block {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-popup-label-padding-inline {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-popup-label-font-size {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-popup-label-font-weight {
  syntax: "<number>";
  inherits: true;
  initial-value: 400;
}

@property --cui-popup-label-letter-spacing {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-popup-label-text-transform {
  syntax: "none | uppercase | lowercase | capitalize";
  inherits: true;
  initial-value: none;
}

@property --cui-popup-separator-inset {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-popup-shortcut-font-size {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-popup-shortcut-letter-spacing {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --_popover-viewport-height {
  syntax: "<length> | auto";
  inherits: false;
  initial-value: auto;
}

@layer components {
  :where([data-control-family="popup"][data-popup-kind="popover"][data-slot="viewport"]) {
    block-size: var(--_popover-viewport-height, auto);
    overflow: clip;
    transition: block-size var(--duration-base) var(--ease-emphasized);
  }

  :where([data-control-family="popup"][data-popup-kind="popover"][data-slot="viewport-content"]) {
    display: flow-root;
  }

  :where([data-control-family="popup"][data-popup-kind="sheet"][data-popup-part="surface"]) {
    transition-property: translate;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-emphasized);
    border-radius: 0;
    border-style: solid;
    border-width: 0px;
  }

  :where(
    [data-control-family="popup"][data-popup-kind="sheet"][data-popup-part="surface"][data-side="left"]:is(
      [data-starting-style],
      [data-ending-style]
    )
  ) {
    translate: -100% 0;
  }

  :where(
    [data-control-family="popup"][data-popup-kind="sheet"][data-popup-part="surface"][data-side="right"]:is(
      [data-starting-style],
      [data-ending-style]
    )
  ) {
    translate: 100% 0;
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"]) {
    font-size: var(--text-label);
    line-height: 1.35;
    text-wrap: balance;
    transition-property: opacity, scale;
    transition-timing-function: var(--ease-standard);
    transition-duration: var(--duration-fast);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"][data-instant]) {
    transition-property: none;
  }

  :where(
    [data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"][data-popup-part="surface"]:not([data-arrow="true"])
  ) {
    --_popup-tooltip-content-radius: var(--cui-popup-radius);
    border-radius: var(--_popup-tooltip-content-radius);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"][data-popup-part="surface"][data-arrow="true"]) {
    --_popup-tooltip-content-radius: clamp(0px, var(--cui-popup-radius), 3px);
    border-radius: var(--_popup-tooltip-content-radius);
  }
}

@layer components {
  :where([data-control-family="popup"][data-popup-part="surface"]),
  :where([data-control-family="popup"][data-popup-part="list-surface"]),
  :where([data-control-family="popup"][data-popup-part="bar"]) {
    --cui-popup-radius: var(--radius-popover);
    --cui-popup-background: var(--popover);
